package com.northstar.crm.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * Request body for {@code POST /api/v1/customers}. The public ID ({@code CUS-####}) is
 * generated by the server, never supplied by the client. Status mirrors the {@code
 * ck_customer_status} database constraint.
 */
public record CreateCustomerRequest(
    @NotBlank @Size(max = 200) String fullName,
    @NotBlank
        @Pattern(
            regexp = "PROSPECT|ACTIVE",
            message = "status must be PROSPECT or ACTIVE when creating a customer")
        String status) {}
